  /* ---- overrides of core.js functions (redeclare to extend theme-aware behavior) ---- */
  function renderThemeChrome(key) {
    var t = THEMES[key];
    $("app-title").textContent = t.title;
    $("brand-chip").textContent = t.brandChip;
    $("card-icon").innerHTML = ICONS[t.logo];
    $("card-kicker").textContent = t.kicker;
    $("card-name").textContent = t.name;
    $("card-rank").textContent = t.rank;
    var photoVal = t.cardPhoto ? PHOTOS[t.cardPhoto] : null;
    $("card").style.setProperty("--card-photo", photoVal ? "url('" + photoVal + "')" : "none");
    var mascot = $("card-mascot");
    if (key === "wakaoshi") {
      mascot.style.backgroundImage = "url('" + CHAR_PHOTOS.ichiko_chibi + "')";
      mascot.hidden = false;
    } else {
      mascot.hidden = true;
    }
    animateNumber($("card-points"), state.points);
    $("theme-color-meta").setAttribute("content", t.accentStrong);
  }

  function renderPanelCopy() {
    if (state.theme === "sports") {
      $("quests-lead").textContent = "日常の移動や決済、スタジアム訪問でポイントが貯まります（追加原価ゼロ設計）。新しいクエストが追加されました。";
      $("rewards-lead").textContent = "手数料がかからない、自社グループおよび地元提携企業の限定特典。コラボ景品が追加されました。";
    } else if (state.theme === "wakaoshi") {
      $("quests-lead").textContent = "まちを歩いて物語を発見。わかおしっ！限定クエストが追加されました。";
      $("rewards-lead").textContent = "手数料がかからない、自社グループの限定特典。わかおしっ！限定アイテムが追加されました。";
    } else {
      $("quests-lead").textContent = "日常のお取引やお手続きでポイントが貯まります。";
      $("rewards-lead").textContent = "手数料がかからない、自社グループの限定特典です。";
    }
  }

  function renderPromo() {
    $("gacha-promo").hidden = state.theme !== "sports";
    $("story-gauge").hidden = state.theme !== "wakaoshi";
    $("char-showcase").hidden = state.theme !== "wakaoshi";
    if (state.theme === "wakaoshi") {
      renderStoryGauge();
      renderCharShowcase();
      $("photo-credit").textContent = "イラスト: 和歌山市シティプロモーション「わかおしっ」公式サイトより／写真: Wikimedia Commons（CC BY / CC BY-SA / CC0）";
    } else {
      $("photo-credit").textContent = "写真: Wikimedia Commons（CC BY / CC BY-SA / CC0）";
    }
  }

  function setTab(tab) {
    state.tab = tab;
    ["home", "quests", "rewards", "history"].forEach(function (name) {
      var panel = $("panel-" + name);
      panel.hidden = name !== tab;
    });
    $("mode-switch").hidden = tab !== "home";
    var current = $("panel-" + tab);
    current.classList.remove("tab-enter");
    void current.offsetWidth;
    current.classList.add("tab-enter");

    document.querySelectorAll(".nav-item").forEach(function (btn) {
      if (btn.dataset.tab === tab) btn.setAttribute("aria-current", "page");
      else btn.removeAttribute("aria-current");
    });

    if (tab === "history") renderHistory();
  }

  function renderRewards() {
    $("gacha-hero").hidden = state.theme !== "sports";

    var list = $("reward-list");
    list.innerHTML = "";

    var order = [];
    var groups = {};
    activeRewards().forEach(function (r) {
      if (!groups[r.type]) { groups[r.type] = []; order.push(r.type); }
      groups[r.type].push(r);
    });

    order.forEach(function (type) {
      var section = document.createElement("div");
      section.className = "reward-category";

      var title = document.createElement("h3");
      title.className = "reward-category-title";
      title.textContent = type;
      section.appendChild(title);

      var grid = document.createElement("div");
      grid.className = "reward-category-grid";
      groups[type].forEach(function (r, i) {
        grid.appendChild(buildCouponCard(r, i, true));
      });
      section.appendChild(grid);

      list.appendChild(section);
    });
  }

  /* ---- new functions: character showcase, story gauge, theme transition, gacha, sakura ---- */
  function renderCharShowcase() {
    var scroll = $("char-scroll");
    if (scroll.childElementCount) return;
    var order = ["ichiko", "wakako", "joko", "takenoko", "taiko", "ebiko"];
    order.forEach(function (key) {
      var meta = CHAR_META[key];
      var card = document.createElement("button");
      card.type = "button";
      card.className = "char-card";

      var photo = document.createElement("div");
      photo.className = "char-card-photo";
      photo.style.backgroundImage = "url('" + CHAR_PHOTOS[key + "_chibi"] + "')";

      var name = document.createElement("div");
      name.className = "char-card-name";
      name.textContent = meta.name;

      var area = document.createElement("div");
      area.className = "char-card-area";
      area.textContent = meta.area;

      card.appendChild(photo);
      card.appendChild(name);
      card.appendChild(area);
      card.addEventListener("click", function () {
        showToast(meta.name + "「" + meta.blurb + "」");
      });
      scroll.appendChild(card);
    });
  }

  function renderStoryGauge() {
    var idx = Math.min(state.storyScore, STORY_CHAPTERS.length) - 1;
    $("story-chapter").textContent = STORY_CHAPTERS[Math.max(0, idx)];
    $("story-score").textContent = state.storyScore + "/5";
    $("story-fill").style.width = (state.storyScore / 5 * 100) + "%";
  }

  function applyTheme(next) {
    state.theme = next;
    document.body.setAttribute("data-app-theme", next);
    document.querySelectorAll(".mode-pill").forEach(function (p) {
      if (p.dataset.theme === next) p.setAttribute("aria-current", "page");
      else p.removeAttribute("aria-current");
    });
    renderThemeChrome(next);
    renderPanelCopy();
    renderPromo();
    renderQuests();
    renderRewards();
    renderHomePreview();

    if (next === "wakaoshi") startSakuraAmbient();
    else stopSakuraAmbient();
  }

  function switchTheme(next, e) {
    if (state.isTransitioning || next === state.theme) return;
    var ox = (e && e.clientX) || window.innerWidth / 2;
    var oy = (e && e.clientY) || window.innerHeight / 2;
    playModeTransition(next, ox, oy);
  }

  function playModeTransition(next, ox, oy) {
    if (reduceMotion) { applyTheme(next); return; }

    state.isTransitioning = true;
    var modePills = document.querySelectorAll(".mode-pill");
    modePills.forEach(function (p) { p.disabled = true; });

    var overlay = $("mode-transition");
    var badge = $("transition-badge");
    var t = THEMES[next];

    overlay.style.background = TRANSITION_GRADIENTS[next];
    var iconWrap = $("badge-icon-wrap");
    if (next === "wakaoshi") {
      iconWrap.className = "badge-icon-wrap char-badge";
      iconWrap.innerHTML = '<img src="' + CHAR_PHOTOS.ichiko_full + '" alt="" />';
    } else {
      iconWrap.className = "badge-icon-wrap";
      iconWrap.innerHTML = ICONS[t.logo];
    }
    $("badge-title").textContent = t.badgeTitle;
    $("badge-sub").textContent = t.badgeSub;

    var maxRadius = Math.hypot(
      Math.max(ox, window.innerWidth - ox),
      Math.max(oy, window.innerHeight - oy)
    ) + 40;

    app.classList.add("mode-warp");
    flashPulse("rgba(255,255,255,.85)");

    overlay.style.clipPath = "circle(0px at " + ox + "px " + oy + "px)";
    var openAnim = overlay.animate(
      [
        { clipPath: "circle(0px at " + ox + "px " + oy + "px)" },
        { clipPath: "circle(" + maxRadius + "px at " + ox + "px " + oy + "px)" }
      ],
      { duration: 620, easing: "cubic-bezier(.65,0,.35,1)", fill: "forwards" }
    );

    badge.classList.remove("show");
    void badge.offsetWidth;
    badge.classList.add("show");

    openAnim.onfinish = function () {
      applyTheme(next);

      requestAnimationFrame(function () {
        var closeAnim = overlay.animate(
          [
            { clipPath: "circle(" + maxRadius + "px at " + ox + "px " + oy + "px)" },
            { clipPath: "circle(0px at " + ox + "px " + oy + "px)" }
          ],
          { duration: 520, easing: "cubic-bezier(.65,0,.35,1)", fill: "forwards" }
        );
        fireConfetti(ox, oy, t.confetti, 130);
        app.classList.remove("mode-warp");

        closeAnim.onfinish = function () {
          badge.classList.remove("show");
          overlay.style.clipPath = "circle(0px at 50% 50%)";
          modePills.forEach(function (p) { p.disabled = false; });
          state.isTransitioning = false;
        };
      });
    };
  }

  function pickPrize() {
    var r = Math.random() * 100;
    var acc = 0;
    for (var i = 0; i < GACHA_POOL.length; i++) {
      acc += GACHA_POOL[i].weight;
      if (r <= acc) return GACHA_POOL[i];
    }
    return GACHA_POOL[GACHA_POOL.length - 1];
  }

  function drawGacha() {
    if (state.isTransitioning) return;
    if (state.points < GACHA_COST) {
      showToast("ポイントが不足しています");
      return;
    }

    var btn = $("gacha-btn");
    var capsule = $("gacha-capsule");
    var result = $("gacha-result");
    var status = $("gacha-status");
    btn.disabled = true;
    btn.textContent = "抽選中…";
    status.hidden = false;
    result.hidden = true;
    result.classList.remove("show");

    if (reduceMotion) {
      finishGacha();
      return;
    }

    capsule.classList.remove("idle");
    capsule.classList.add("shaking");

    setTimeout(function () {
      capsule.classList.remove("shaking");
      capsule.classList.add("popping");
      setTimeout(finishGacha, 380);
    }, 550);

    function finishGacha() {
      status.hidden = true;
      state.points -= GACHA_COST;
      animateNumber($("card-points"), state.points);

      var prize = pickPrize();
      logHistory("ガチャを回す", prize.name + "（" + prize.rarity + "）が当選", -GACHA_COST);
      result.hidden = false;
      result.className = "gacha-result rarity-" + prize.rarity.toLowerCase();
      result.innerHTML =
        '<span class="rarity-badge rarity-' + prize.rarity.toLowerCase() + '">' + prize.rarity + "</span>" +
        '<p class="prize-name">' + prize.name + "</p>";
      requestAnimationFrame(function () { result.classList.add("show"); });

      var rect = capsule.getBoundingClientRect();
      var cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
      fireConfetti(cx, cy, RARITY_COLORS[prize.rarity], RARITY_CONFETTI_COUNT[prize.rarity]);
      if (prize.rarity === "SSR") flashPulse("rgba(245,158,11,.6)");

      capsule.classList.remove("shaking", "popping");
      capsule.classList.add("idle");
      btn.disabled = false;
      btn.textContent = "もう一度回す（" + GACHA_COST + "pt）";
    }
  }

  function flashPulse(color) {
    if (reduceMotion) return;
    var el = $("flash-pulse");
    el.style.background = color;
    el.animate(
      [{ opacity: 0 }, { opacity: .55, offset: .18 }, { opacity: 0 }],
      { duration: 480, easing: "ease-out" }
    );
  }

  var sakuraState = { running: false, particles: [], raf: null, canvas: null, ctx: null };

  function startSakuraAmbient() {
    if (reduceMotion || sakuraState.running) return;
    var canvas = $("sakura-canvas");
    sakuraState.canvas = canvas;
    sakuraState.ctx = canvas.getContext("2d");
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    canvas.classList.add("active");

    var count = window.innerWidth < 480 ? 22 : 34;
    sakuraState.particles = [];
    for (var i = 0; i < count; i++) {
      sakuraState.particles.push(spawnPetal(true));
    }
    sakuraState.running = true;

    function spawnPetal(randomY) {
      return {
        x: Math.random() * canvas.width,
        y: randomY ? Math.random() * canvas.height : -20,
        size: 7 + Math.random() * 8,
        speedY: 0.6 + Math.random() * 1.1,
        speedX: -0.4 + Math.random() * 0.8,
        sway: Math.random() * Math.PI * 2,
        swaySpeed: 0.01 + Math.random() * 0.02,
        swayAmp: 18 + Math.random() * 26,
        rot: Math.random() * 360,
        rotSpeed: (Math.random() - 0.5) * 2.4,
        opacity: 0.45 + Math.random() * 0.4,
        hue: Math.random() < 0.5 ? "#f9a8d4" : "#fbcfe8"
      };
    }

    function drawPetal(p) {
      var ctx = sakuraState.ctx;
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate((p.rot * Math.PI) / 180);
      ctx.globalAlpha = p.opacity;
      ctx.fillStyle = p.hue;
      ctx.beginPath();
      ctx.moveTo(0, -p.size);
      ctx.bezierCurveTo(p.size * 0.8, -p.size * 0.6, p.size * 0.8, p.size * 0.6, 0, p.size);
      ctx.bezierCurveTo(-p.size * 0.8, p.size * 0.6, -p.size * 0.8, -p.size * 0.6, 0, -p.size);
      ctx.fill();
      ctx.restore();
    }

    function tick() {
      if (!sakuraState.running) return;
      var ctx = sakuraState.ctx;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      sakuraState.particles.forEach(function (p) {
        p.sway += p.swaySpeed;
        p.y += p.speedY;
        p.x += p.speedX + Math.sin(p.sway) * (p.swayAmp * 0.02);
        p.rot += p.rotSpeed;
        if (p.y > canvas.height + 20) {
          Object.assign(p, spawnPetal(false));
        }
        if (p.x > canvas.width + 20) p.x = -20;
        if (p.x < -20) p.x = canvas.width + 20;
        drawPetal(p);
      });
      sakuraState.raf = requestAnimationFrame(tick);
    }
    tick();
  }

  function stopSakuraAmbient() {
    sakuraState.running = false;
    if (sakuraState.raf) cancelAnimationFrame(sakuraState.raf);
    var canvas = $("sakura-canvas");
    canvas.classList.remove("active");
    setTimeout(function () {
      if (!sakuraState.running && sakuraState.ctx) {
        sakuraState.ctx.clearRect(0, 0, canvas.width, canvas.height);
      }
    }, 650);
  }

  /* ---- event wiring ---- */
  document.querySelectorAll(".mode-pill").forEach(function (pill) {
    pill.addEventListener("click", function (e) { switchTheme(pill.dataset.theme, e); });
  });
  $("gacha-btn").addEventListener("click", drawGacha);
  $("gacha-promo").addEventListener("click", function () { setTab("rewards"); });

  $("story-gauge-btn").addEventListener("click", function () {
    state.storyScore = state.storyScore >= 5 ? 1 : state.storyScore + 1;
    renderStoryGauge();
    var rect = $("story-gauge-btn").getBoundingClientRect();
    if (state.storyScore >= 5) {
      showToast("全5章を読破！コンプリート特典をチェックしよう");
      fireConfetti(rect.left + rect.width / 2, rect.top + rect.height / 2, THEMES.wakaoshi.confetti, 120);
    } else {
      showToast("第" + state.storyScore + "章「" + STORY_CHAPTERS[state.storyScore - 1] + "」が解放されました");
      fireConfetti(rect.left + rect.width / 2, rect.top + rect.height / 2, THEMES.wakaoshi.confetti, 50);
    }
  });

  window.addEventListener("resize", function () {
    if (sakuraState.canvas) {
      sakuraState.canvas.width = window.innerWidth;
      sakuraState.canvas.height = window.innerHeight;
    }
  });
